    for i in opens:
        start_j = bisect.bisect_right(closes, i)
        for j in closes[start_j:]:
            k_idx = bisect.bisect_right(opens, i)
            if k_idx >= len(opens):
                continue
            k = opens[k_idx]
            if k >= j:
                continue
            l_idx = bisect.bisect_right(closes, k)
            if l_idx >= len(closes):
                continue
            l = closes[l_idx]
            if l <= j and l > k:
